import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('list_sessions frame validation', () => {
  it('accepts a bare list_sessions frame and strips unknown fields like userId', () => {
    expect(validateMessage({type: 'list_sessions', userId: 'u2'})).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });
  });

  it('accepts list_sessions with valid integer limit and before cursor', () => {
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};
    expect(validateMessage({type: 'list_sessions', limit: 10, before})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before},
    });
  });

  it('rejects a string limit and names the field', () => {
    expect(validateMessage({type: 'list_sessions', limit: 'ten'})).toMatchObject({
      valid: false,
      error: expect.stringContaining('limit'),
    });
  });

  it('rejects a negative limit', () => {
    expect(validateMessage({type: 'list_sessions', limit: -1})).toMatchObject({
      valid: false,
      error: expect.stringContaining('limit'),
    });
  });

  it('rejects a fractional limit', () => {
    expect(validateMessage({type: 'list_sessions', limit: 1.5})).toMatchObject({
      valid: false,
      error: expect.stringContaining('limit'),
    });
  });

  it('rejects a non-object before cursor and names the field', () => {
    expect(validateMessage({type: 'list_sessions', before: 'not-an-object'})).toMatchObject({
      valid: false,
      error: expect.stringContaining('before'),
    });
  });

  it('rejects a before cursor with an empty sessionId', () => {
    expect(
      validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}})
    ).toMatchObject({valid: false, error: expect.stringContaining('before')});
  });

  it('rejects a before cursor with sessionId longer than 128 chars', () => {
    expect(
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      })
    ).toMatchObject({valid: false, error: expect.stringContaining('before')});
  });

  it('rejects a before cursor with an unparseable updatedAt', () => {
    expect(validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}})).toMatchObject({
      valid: false,
      error: expect.stringContaining('before'),
    });
  });

  it('rejects a before cursor with a boolean updatedAt', () => {
    expect(validateMessage({type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}})).toMatchObject({
      valid: false,
      error: expect.stringContaining('before'),
    });
  });
});

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });
});

